from bs4 import BeautifulSoup
from taf.ul.oam.selenium_core.exceptions import ColumnDoesNotExist, AttributeDoesNotExist, CouldNotFindObject, DegeneratedTable
from selenium.common.exceptions import NoSuchElementException


class HTMLTable(object):
    """
    HTMLTable class parse tables from WebUI on MzOAM and cOAM and allows
    simple operations on it. It is working only with <table> HTML object.
    Selenium WebDriver and xpath to desired table object is the only
    required thing to parse whole table and perform operations on it.
    When table header is not available in WebUI, then column names are default:
    'Unnamed column 0', 'Unnamed column 1', ...

    -DegeneratedTable exception will be raised if table does not contain any single row or header.
    """
    def __init__(self, driver, xpath):
        """
        Constructor of HTMLTable class
        :param driver: Selenium WebDriver
        :param xpath: xpath to desired table object
        :type xpath: string

        -CouldNotFindObject exception will be raised if it will be impossible to find
        element by given xpath.

        -AttributeDoesNotExist exception will be raised if table object won't have desired
        attribute (e.g. outerHTML or class).
        """
        try:
            _web_element = driver.find_element_by_xpath(xpath)
        except NoSuchElementException:
            raise CouldNotFindObject("Object with xpath {} does not exist.".format(xpath))
        _table = self._get_attribute_value(_web_element, 'outerHTML')
        self._soup = BeautifulSoup(_table, 'lxml')
        _class = self._get_attribute_value(_web_element, 'class')
        self._parsed_data = self._parse_table(_class)

    def get_column_from_table(self, column_name):
        """
        Returns whole column from parsed table by its name
        :param column_name: name of the column to be returned, when table header is not available in WebUI,
        then column names are default: 'Unnamed column 0', 'Unnamed column 1', ...
        :type column_name: str
        :return list with desired column values
        :rtype list of strings
        Method raises ColumnDoesNotExist exception if column with given name is not present in the table.
        """
        try:
            return self._parsed_data[column_name]
        except KeyError:
            raise ColumnDoesNotExist("Column {0} is not present in table".format(column_name))

    def get_cell_from_table(self, column_name, index):
        """
        Returns specific cell from given column and row of table.
        Index starts at 0 (without header)
        :param column_name: name of the column which contains desired value,
        when table header is not available in WebUI, then column names are default:
        'Unnamed column 0', 'Unnamed column 1', ...
        :type column_name: string
        :param index: index to desired row
        :type index: int
        :return: cell value
        :rtype: str
        Method raises ColumnDoesNotExist exception if desired column name is not present in the table.
        Method raises IndexError exception if particular index is not present in the table.
        """
        try:
            return self._parsed_data[column_name][index]
        except KeyError:
            raise ColumnDoesNotExist("Column {0} is not present in table".format(column_name))
        except IndexError:
            raise IndexError('Column {0} does not contain requested index: {1}'.format(column_name, index))

    def get_row_from_table(self, index):
        """
        Returns whole row from parsed table by its index
        :param index: row with given index to be returned, starts from 0 (without header)
        :type index: int
        :return dictionary with pairs column_name: value of given cell
        :rtype dict
        Method raises IndexError exception if index is not present in the table.
        """
        try:
            return {key: self._parsed_data[key][index] for key in self._parsed_data}
        except IndexError:
            raise IndexError("Row with index {0} is not present in table".format(index))

    def get_table(self):
        """
        Returns whole table parsed by HTML Table as dict.
        Keys in dictionary are column names, where values are lists
        of strings with corresponding values of given column.
        :return parsed table
        :rtype dict
        """
        return self._parsed_data

    def _get_attribute_value(self, web_element, attribute_name):
        attribute = web_element.get_attribute(attribute_name)
        if attribute is None:
            raise AttributeDoesNotExist("Given table does not have {0} attribute.".format(attribute_name))
        else:
            return attribute

    def _get_column_names(self):
        column_names = []

        header = self._soup.find('thead')
        if not header:
            return column_names

        header_rows = header.find_all('th')
        if header_rows:
            for col in header_rows:
                column_names.append(str(col.text))

        return column_names

    def _verify_column_names(self, colnames):
        verified_colnames = []
        for i, name in enumerate(colnames):
            name = "Unnamed column: {}".format(i) if name == '' else name
            verified_colnames.append(name)
        return verified_colnames

    def _create_default_colnames(self, row_length):
        column_names = ["Unnamed column: {0}".format(number) for number in range(row_length)]
        return column_names

    def _parse_rows_from_trs(self, trs):
        rows = []
        for tr in trs:
            cells = tr.find_all('td')
            if cells and not all(cell == '' for cell in cells):
                cells = [str(cell.text) for cell in cells]
                rows.append(cells)
        return rows

    def _parse_tr_from_table(self, class_attr):
        trs = []
        table = self._soup.find('table', attrs={'class': class_attr})
        if not table:
            return trs
        table_body = table.find('tbody')
        if not table_body:
            return trs
        trs = table_body.find_all('tr')
        return trs

    def _get_rows(self, class_attr):
        table_rows = []
        trs = self._parse_tr_from_table(class_attr)
        if trs:
            table_rows = self._parse_rows_from_trs(trs)
        return table_rows

    def _get_parsed_dict(self, rows, column_names):
        parsed_dict = {}
        for column_id, key in enumerate(column_names):
            parsed_dict[key] = [row[column_id] for row in rows]
        return parsed_dict

    def _create_empty_dict(self, col_names):
        empty_dict = {name: [] for name in col_names}
        return empty_dict

    def _parse_table(self, class_attr):
        column_names = self._get_column_names()

        rows = self._get_rows(class_attr)

        if not rows and column_names:
            return self._create_empty_dict(column_names)

        if not rows and not column_names:
            raise DegeneratedTable("It is impossible to parse - table contains nor rows neither columns!")

        if rows and not column_names:
            column_names = self._create_default_colnames(len(rows[0]))

        column_names = self._verify_column_names(column_names)

        parsed_dict = self._get_parsed_dict(rows, column_names)
        return parsed_dict
